package com.bank.flink.late;

import java.math.BigDecimal;

// A transaction with a business event time (may arrive out of order).
class Txn {
    private final String txnId;
    private final BigDecimal amount;
    private final long eventTimeMillis;

    Txn(String txnId, BigDecimal amount, long eventTimeMillis) {
        this.txnId = txnId;
        this.amount = amount;
        this.eventTimeMillis = eventTimeMillis;
    }

    String getTxnId() { return txnId; }
    BigDecimal getAmount() { return amount; }
    long getEventTimeMillis() { return eventTimeMillis; }
}
