package com.bank.flink.late;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// One 1-hour tumbling window for a single branch, with allowed lateness
// and a side output for events too late to count.
class TumblingWindowAggregator {
    private static final Logger log = Logger.getLogger(TumblingWindowAggregator.class.getName());

    private final long windowStart;      // inclusive
    private final long windowEnd;        // exclusive
    private final long allowedLatenessMs; // grace after firing

    private BigDecimal total = BigDecimal.ZERO;
    private int count = 0;
    private boolean fired = false;
    private final List<Txn> sideOutput = new ArrayList<>(); // too-late stragglers

    TumblingWindowAggregator(long windowStart, long windowEnd, long allowedLatenessMs) {
        this.windowStart = windowStart;
        this.windowEnd = windowEnd;
        this.allowedLatenessMs = allowedLatenessMs;
    }

    // Returns true if the txn was counted (on time or within allowed lateness).
    boolean accept(Txn t, long currentWatermark) {
        boolean inWindow = t.getEventTimeMillis() >= windowStart && t.getEventTimeMillis() < windowEnd;
        if (!inWindow) return false;

        if (!fired) {
            total = total.add(t.getAmount());
            count++;
            log.info(() -> "counted on-time " + t.getTxnId() + " amount=" + t.getAmount());
            return true;
        }
        // Window already fired: is the event within allowed lateness?
        if (currentWatermark <= windowEnd + allowedLatenessMs) {
            total = total.add(t.getAmount());
            count++;
            log.warning(() -> "LATE but within grace: " + t.getTxnId()
                    + " -> emit UPDATED total=" + total);
            return true;
        }
        // Too late: side output, never silently dropped.
        sideOutput.add(t);
        log.severe(() -> "TOO LATE -> side output " + t.getTxnId());
        return false;
    }

    // Watermark passed window end: fire the first result.
    void maybeFire(long watermark) {
        if (!fired && watermark >= windowEnd) {
            fired = true;
            log.info(() -> "FIRE window [" + windowStart + "," + windowEnd + ") total="
                    + total + " count=" + count);
        }
    }

    BigDecimal getTotal() { return total; }
    List<Txn> getSideOutput() { return sideOutput; }
}
