package com.bank.flink.late;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class LateDataDemo {
    private static final Logger log = Logger.getLogger(LateDataDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        long hour = 60L * 60 * 1000;
        long min = 60L * 1000;
        // Window [0, 1h), allowed lateness 15 minutes.
        TumblingWindowAggregator win = new TumblingWindowAggregator(0, hour, 15 * min);

        long wm = 0;
        // On-time transactions inside the window.
        win.accept(new Txn("T1", new BigDecimal("50000"), 10 * min), wm);
        win.accept(new Txn("T2", new BigDecimal("12000"), 40 * min), wm);

        // Watermark advances to window end -> window fires.
        wm = hour;
        win.maybeFire(wm);

        // Slightly late txn (event time inside window) within 15-min grace.
        wm = hour + 10 * min;
        win.accept(new Txn("T3", new BigDecimal("8000"), 55 * min), wm);

        // Very late txn beyond the 15-min grace -> side output.
        wm = hour + 20 * min;
        win.accept(new Txn("T4", new BigDecimal("3000"), 50 * min), wm);

        log.info("final window total = " + win.getTotal());
        log.info("side-output stragglers = " + win.getSideOutput().size());
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
